import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import squizInfoMock from '@ntgovernment/squiz-factory/plugins/squizInfo.mock';
import comp from './main.js';



/**
 * Shaped to match the real MatrixAssetSchema.json (per this project's card/
 * image-gallery components' own confirmed inspection): `name` (not `title`),
 * `url`, `metadata` as a key-value map of string arrays. The document mocks'
 * top-level `file_type`/`file_size` fields are unconfirmed against a real
 * backend -- see topic-listing.spec.md assumption 2.
 */
function fakePage({ id, name, description }) {
  return {
    id: String(id),
    type: 'pageStandard',
    name,
    url: `https://example.com/pages/${id}`,
    metadata: description ? { Description: [description] } : {},
    child_count: 0,
  };
}

function fakeDocument({ id, name, fileType, fileSize }) {
  return {
    id: String(id),
    type: 'file',
    name,
    url: `https://example.com/assets/${id}.${fileType}`,
    file_type: fileType,
    file_size: fileSize,
  };
}

const FAKE_ASSETS = {
  'matrix-asset://ntg/5001': fakePage({
    id: 5001,
    name: 'Topic title',
    description: 'A short description about the topic and what the user expect to find here.',
  }),
  'matrix-asset://ntg/5101': fakePage({ id: 5101, name: 'Link sample text' }),
  'matrix-asset://ntg/5102': fakePage({ id: 5102, name: 'Link sample text' }),
  'matrix-asset://ntg/5201': fakeDocument({ id: 5201, name: 'This is the document title', fileType: 'pdf', fileSize: 186368 }),
  'matrix-asset://ntg/5202': fakeDocument({ id: 5202, name: 'This is the document title', fileType: 'docx', fileSize: 186368 }),
  'matrix-asset://ntg/5203': fakeDocument({ id: 5203, name: 'This is the document title', fileType: 'pptx', fileSize: 186368 }),
  'matrix-asset://ntg/5204': fakeDocument({ id: 5204, name: 'This is the document title', fileType: 'xlsx', fileSize: 186368 }),
  'matrix-asset://ntg/5301': fakePage({ id: 5301, name: 'Child care subsidies', description: 'Find eligibility criteria, payment schedules, and how to apply.' }),
  'matrix-asset://ntg/5302': fakePage({ id: 5302, name: 'Support for carers', description: 'Access respite programs, allowances, and local support groups.' }),
  'matrix-asset://ntg/5303': fakePage({ id: 5303, name: 'Community grants', description: 'Explore funding rounds for local projects and community initiatives.' }),
  'matrix-asset://ntg/5304': fakePage({ id: 5304, name: 'Parenting resources', description: 'Guidance for early years, school readiness, and family wellbeing.' }),
};

function resolveUriMock(uri) {
  return FAKE_ASSETS[uri] ?? null;
}

/**
 * squizStoryRenderer's installed signature only takes `main` -- the mock
 * `info`/`fns` is supplied at each render call site instead of baked into
 * the constructor (see card.stories.js / image-gallery.stories.js for the
 * same correction, and their comments for exactly why the old
 * constructor-argument pattern silently did nothing).
 */
const squiz = squizStoryRenderer(comp.main);
const mockInfo = squizInfoMock({ mock: { resolveUri: resolveUriMock } });

export default {
  title: 'dxp/Topic Listing',
  parameters: {
    layout: 'padded',
  },
};

const topicsArgs = {
  topicSource: 'matrix-asset://ntg/5001',
  linkSources: [
    'matrix-asset://ntg/5301',
    'matrix-asset://ntg/5302',
    'matrix-asset://ntg/5303',
    'matrix-asset://ntg/5304',
  ],
};
const topicsHtml = await squiz.markup(topicsArgs, mockInfo);

export const Topics = {
  render: (args) => squiz(args, mockInfo),
  args: topicsArgs,
  argTypes: {
    topicSource: {
      control: 'text',
      description: 'matrix-asset-uri for the main topic page. Only these demo URIs resolve to anything in this Storybook preview (mocked): matrix-asset://ntg/5001 (topic), matrix-asset://ntg/5101, matrix-asset://ntg/5102 (plain-link pages), matrix-asset://ntg/5201-5204 (documents), matrix-asset://ntg/5301-5304 (child-topic pages, each with its own description).',
    },
    linkSources: { control: 'object' },
  },
  parameters: {
    docs: {
      description: { story: '`linkSources` resolves to pages that each have their own metadata.Description -- these render as child-topic items (title + description, no bullet), distinct from the plain bulleted links in the Links story.' },
      source: { code: topicsHtml, language: 'html', type: 'code' },
    },
  },
};

const linksArgs = {
  topicSource: 'matrix-asset://ntg/5001',
  linkSources: [
    'matrix-asset://ntg/5101', 'matrix-asset://ntg/5102', 'matrix-asset://ntg/5101', 'matrix-asset://ntg/5102',
    'matrix-asset://ntg/5101', 'matrix-asset://ntg/5102', 'matrix-asset://ntg/5101', 'matrix-asset://ntg/5102',
    'matrix-asset://ntg/5101', 'matrix-asset://ntg/5102',
  ],
};
const linksHtml = await squiz.markup(linksArgs, mockInfo);

export const Links = {
  render: () => squiz(linksArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'Every `linkSources` entry resolves to a page -- each renders as a plain bulleted link, in a two-column grid at the `md` breakpoint and up, one column on mobile.' },
      source: { code: linksHtml, language: 'html', type: 'code' },
    },
  },
};

const documentsArgs = {
  topicSource: 'matrix-asset://ntg/5001',
  linkSources: [
    'matrix-asset://ntg/5201', 'matrix-asset://ntg/5202', 'matrix-asset://ntg/5203', 'matrix-asset://ntg/5204',
    'matrix-asset://ntg/5201', 'matrix-asset://ntg/5202', 'matrix-asset://ntg/5203', 'matrix-asset://ntg/5204',
    'matrix-asset://ntg/5201', 'matrix-asset://ntg/5202',
  ],
};
const documentsHtml = await squiz.markup(documentsArgs, mockInfo);

export const Documents = {
  render: () => squiz(documentsArgs, mockInfo),
  parameters: {
    docs: {
      description: { story: 'Every `linkSources` entry resolves to a file -- each renders as a document item (file-type icon, bold title, format + size), in a two-column grid at the `md` breakpoint and up, one column on mobile.' },
      source: { code: documentsHtml, language: 'html', type: 'code' },
    },
  },
};
