/**
 * Topic Listing DXP Component -- Server-Side Renderer
 *
 * Resolves one topic page and a list of other pages/documents via
 * info.fns.resolveUri, mirroring this project's `card`/`image-gallery`
 * resolution architecture -- best-effort per source, never throws. See
 * topic-listing.spec.md assumptions 1-2 for exactly what's confirmed vs
 * inferred about the Matrix asset schema this relies on.
 */

const FILE_ICONS = {
  pdf: "fa-file-pdf",
  doc: "fa-file-word",
  docx: "fa-file-word",
  ppt: "fa-file-powerpoint",
  pptx: "fa-file-powerpoint",
  xls: "fa-file-excel",
  xlsx: "fa-file-excel",
};
const DEFAULT_FILE_ICON = "fa-file";

function esc(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function firstMetadataValue(metadata, key) {
  const value = metadata?.[key];
  return Array.isArray(value) ? (value[0] || "") : "";
}

/**
 * Maps a resolved topic page onto {title, description, href}, reusing
 * `card`'s own confirmed/assumed metadata conventions (name/url/metadata.Description)
 * -- see topic-listing.spec.md assumption 1.
 */
function toTopic(page) {
  if (!page) return null;
  const metadata = page.metadata || {};
  return {
    title: page.name || "",
    description: firstMetadataValue(metadata, "Description"),
    href: page.url || "",
  };
}

/**
 * A resolved asset is treated as a document if its type string mentions
 * "file" (mirroring image-gallery's isFolderAsset substring convention) or
 * it directly exposes a file_type field -- unconfirmed against a real
 * Matrix backend; see topic-listing.spec.md assumption 2.
 */
function isDocumentAsset(asset) {
  const typeString = String(asset?.type ?? asset?.type_name ?? asset?.type_code ?? "").toLowerCase();
  return typeString.includes("file") || Boolean(asset?.file_type);
}

/** Raw byte count -> "182 KB" (rounded, no decimal, matching the source screenshot). */
function formatFileSize(bytes) {
  const value = Number(bytes);
  if (!Number.isFinite(value) || value <= 0) return "";
  return `${Math.round(value / 1024)} KB`;
}

function fileIconClass(fileType) {
  const key = String(fileType ?? "").toLowerCase();
  return FILE_ICONS[key] || DEFAULT_FILE_ICON;
}

/**
 * Maps one resolved asset onto a document item, a child-topic item (a page
 * that has its own metadata.Description -- title + description, no
 * bullet), or a plain link item (a page with no description -- title only,
 * bulleted). The child-topic/plain-link split reuses the same
 * metadata.Description convention as the main topic itself (assumption 1).
 */
function toItem(asset) {
  if (!asset) return null;
  const name = asset.name || "";
  const href = asset.url || "";
  if (!name) return null;

  if (isDocumentAsset(asset)) {
    const fileType = asset.file_type || "";
    const size = formatFileSize(asset.file_size);
    const meta = [fileType.toUpperCase(), size].filter(Boolean).join(" | ");
    return { kind: "document", title: name, href, fileType, meta, iconClass: fileIconClass(fileType) };
  }

  const description = firstMetadataValue(asset.metadata, "Description");
  if (description) {
    return { kind: "child", title: name, href, description };
  }

  return { kind: "link", title: name, href };
}

async function resolveTopic(topicSource, fns) {
  if (!topicSource || typeof fns?.resolveUri !== "function") return null;
  try {
    const resolved = await fns.resolveUri(topicSource);
    return toTopic(resolved);
  } catch {
    return null;
  }
}

async function resolveItems(linkSources, fns) {
  if (!Array.isArray(linkSources) || linkSources.length === 0) return [];
  if (typeof fns?.resolveUri !== "function") return [];

  const items = await Promise.all(linkSources.map(async (source) => {
    if (!source) return null;
    try {
      const resolved = await fns.resolveUri(source);
      return toItem(resolved);
    } catch {
      return null;
    }
  }));

  return items.filter(Boolean);
}

function renderTopic(topic) {
  if (!topic) return "";
  const descriptionHtml = topic.description
    ? `<p class="topic-listing__description">${esc(topic.description)}</p>`
    : "";
  const buttonHtml = topic.href
    ? `<a href="${esc(topic.href)}" class="button button-secondary topic-listing__button">Find out more</a>`
    : "";

  return `
      <div class="topic-listing__topic">
        <h2 class="topic-listing__title">${esc(topic.title)}</h2>
        ${descriptionHtml}
        ${buttonHtml}
      </div>`;
}

function renderLinkItem(item) {
  return `
        <li class="topic-listing__item topic-listing__item--link">
          <span class="topic-listing__bullet" aria-hidden="true"></span>
          <a href="${esc(item.href)}" class="topic-listing__link">${esc(item.title)}</a>
        </li>`;
}

function renderChildItem(item) {
  return `
        <li class="topic-listing__item topic-listing__item--child">
          <a href="${esc(item.href)}" class="topic-listing__child-title">${esc(item.title)}</a>
          <p class="topic-listing__child-description">${esc(item.description)}</p>
        </li>`;
}

function renderDocumentItem(item) {
  return `
        <li class="topic-listing__item topic-listing__item--document">
          <i class="fa-thin ${item.iconClass} topic-listing__doc-icon" aria-hidden="true"></i>
          <div class="topic-listing__doc-body">
            <a href="${esc(item.href)}" class="topic-listing__doc-title">${esc(item.title)}</a>
            ${item.meta ? `<span class="topic-listing__doc-meta">${esc(item.meta)}</span>` : ""}
          </div>
        </li>`;
}

const ITEM_RENDERERS = {
  document: renderDocumentItem,
  child: renderChildItem,
  link: renderLinkItem,
};

function renderItems(items) {
  if (!items || items.length === 0) return "";
  const itemsHtml = items
    .map((item) => ITEM_RENDERERS[item.kind](item))
    .join("\n");

  return `

      <ul class="topic-listing__items">${itemsHtml}
      </ul>`;
}

export default {
  async main(input, info) {
    const { topicSource = "", linkSources = [] } = input || {};
    const fns = info?.fns;

    const [topic, items] = await Promise.all([
      resolveTopic(topicSource, fns),
      resolveItems(linkSources, fns),
    ]);

    if (!topic) return "";

    return /*html*/`
<div class="topic-listing">
  <div class="topic-listing__container">
    <div class="topic-listing__content">${renderTopic(topic)}${renderItems(items)}
    </div>
  </div>
</div>
`;
  },
};
